import{_ as i,a0 as n,w as p,s as d,ao as o,I as l,x as e,a1 as a,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"Web 开发人员喜欢 Brackets 文本编辑器的原因 | LCTT x X-CMD","titleTemplate":false,"description":"Web 开发人员喜欢 Brackets 文本编辑器的原因 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Web 开发人员喜欢 Brackets 文本编辑器的原因 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Web 开发人员喜欢 Brackets 文本编辑器的原因 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201213 What web developers love about the Brackets text editor","title":"Web 开发人员喜欢 Brackets 文本编辑器的原因","tag":"202012","desc":""},"relativePath":"202012/20201213 What web developers love about the Brackets text editor.md","filePath":"[post].md"}'),u={name:"202012/20201213 What web developers love about the Brackets text editor.md"};function k(b,t,f,m,B,T){const r=n("Link");return p(),d("div",null,[t[26]||(t[26]=o('<h1 id="web-开发人员喜欢-brackets-文本编辑器的原因" tabindex="-1">Web 开发人员喜欢 Brackets 文本编辑器的原因 <a class="header-anchor" href="#web-开发人员喜欢-brackets-文本编辑器的原因" aria-label="Permalink to “Web 开发人员喜欢 Brackets 文本编辑器的原因”">​</a></h1><blockquote><p>这个基础的编辑器是面向 Web 开发人员的，它支持多种编程语言，并提供了大量的扩展，使其成为你自己的编辑器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/25/092259zy4xvxs4axmysuf9.jpg" alt=""></p><p>Brackets 文本编辑器是主要面向 Web 开发人员的编辑器。恰如其分的是，它的“编辑”菜单中充满了对 Web 编程语言用户特别有用的功能，主要是 HTML、CSS 和 Javascript 的经典组合。</p><p>但是，它还支持许多与互联网相关的语言和格式，包括 XML、Markdown、YAML 和 JSON、PHP、Lua、Java 和 Python，以及一些常见的通用语言，例如 C、C++，甚至是 <code>diff</code> 命令的输出。</p><h3 id="安装-brackets" tabindex="-1">安装 Brackets <a class="header-anchor" href="#安装-brackets" aria-label="Permalink to “安装 Brackets”">​</a></h3>',6)),l("p",null,[t[1]||(t[1]=e("Brackets 可以从 ",-1)),a(r,{href:"http://brackets.io/"},{default:s(()=>[...t[0]||(t[0]=[e("Brackets 网站",-1)])]),_:1}),t[2]||(t[2]=e("安装到 Linux、Windows 和 macOS 上。",-1))]),l("p",null,[t[4]||(t[4]=e("另外，在 Linux 上，你可以从 ",-1)),a(r,{href:"https://flathub.org/apps/details/io.brackets.Brackets"},{default:s(()=>[...t[3]||(t[3]=[e("flathub.org",-1)])]),_:1}),t[5]||(t[5]=e(" 以 Flatpak 安装。",-1))]),t[27]||(t[27]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/screenshot_2020-12-02_at_16.26.58.png",alt:"Brackets editor",title:"Brackets editor"})],-1)),t[28]||(t[28]=l("h3",{id:"使用-brackets",tabindex:"-1"},[e("使用 Brackets "),l("a",{class:"header-anchor",href:"#使用-brackets","aria-label":"Permalink to “使用 Brackets”"},"​")],-1)),l("p",null,[t[8]||(t[8]=e("在大多数时候，Brackets 是一个“普通”的文本编辑器，其功能类似于 ",-1)),a(r,{href:"https://linux.cn/article-12942-1.html"},{default:s(()=>[...t[6]||(t[6]=[e("jEdit",-1)])]),_:1}),t[9]||(t[9]=e(" 或 ",-1)),a(r,{href:"https://linux.cn/article-12938-1.html"},{default:s(()=>[...t[7]||(t[7]=[e("Medit",-1)])]),_:1}),t[10]||(t[10]=e("。有语法高亮、可配置的制表符间距、字符编码设置等等。这些都可以在窗口底部的状态栏中找到。",-1))]),t[29]||(t[29]=o('<p>在“视图”菜单中，有主题设置、行号、自动换行，甚至还有分割窗口的选项，这样你可以在一个窗口中看到两个文件。</p><p>然而，在“编辑”菜单中，有一些的特别用于编程的功能。以下是我最喜欢的一些功能：</p><ul><li>使用 <code>Ctrl+[</code> 或 <code>Ctrl+]</code> 键盘快捷键来缩进和取消缩进文本块，这不仅对保持 HTML、CSS 和 Javascript 的整洁很有用，而且对 Python 代码也很重要。</li><li>用 <code>Ctrl+/</code> 把一行变成注释。Brackets 标记注释的方式取决于你所使用的语言，所以无论你的文档是否使用斜线、破折号、箭头、井号或其他任何类型注释，这个功能都可以使用。</li><li>用 <code>Shift+Ctrl+Up</code> 或 <code>Shift+Ctrl+Down</code> 在文档中将一行向上或向下移动。</li><li>用 <code>Shift+Ctrl+D</code> 删除整个一行。</li><li>用 <code>Ctrl+D</code> 复制整个一行。</li></ul><p>这些都是看似小众的功能，你可能认为不会经常使用，但一旦你拥有了它们，你就会对它们产生依赖。</p><h3 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to “扩展”">​</a></h3><p>Brackets 还可以接受扩展，因此你和其他编码者可以添加扩展到功能中。要查看有哪些可用的扩展，请单击“文件”菜单并选择“扩展管理器”。有各种各样的扩展，包括用于调整代码格式的 Beautify、用于其他语言的多个支持包、用于转到标签开头或结尾的功能等等。</p><p>无论编辑器是否适合你，扩展可以使一个编辑器变得不同，所以如果你尝试 Brackets 并享受它的一切，但缺少一些重要的功能，在你放弃它之前，请浏览一下可用的扩展。</p><h3 id="尝试-brackets" tabindex="-1">尝试 Brackets <a class="header-anchor" href="#尝试-brackets" aria-label="Permalink to “尝试 Brackets”">​</a></h3><p>Brackets 是一个有点低调的编辑器。虽然它宣传自己是 “Web 代码编辑器”，但实际上它是一个不错的通用编辑器，并为常见的 Web 工具链加入了一些额外的功能。如果你喜欢 Brackets 的外观和它所提供的功能，不妨一试！</p><hr>',10)),l("p",null,[t[12]||(t[12]=e("via: ",-1)),a(r,{href:"https://opensource.com/article/20/12/brackets"},{default:s(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/20/12/brackets",-1)])]),_:1})]),l("p",null,[t[17]||(t[17]=e("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:s(()=>[...t[13]||(t[13]=[e("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:s(()=>[...t[15]||(t[15]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[23]||(t[23]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:s(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const g=i(u,[["render",k]]);export{h as __pageData,g as default};
